mapper.sql:
where is_del = 0

    and space_name like CONCAT('%', #{spaceName,jdbcType=VARCHAR}, '%')


    and space_code = #{spaceCode}


    and status = #{status}

mapper.select:
select from data_trusted_space
order by is_default desc, sort_index asc, space_id asc
limit #{offset}, #{pageSize}

select from data_trusted_space where space_code = #{spaceCode} and is_del = 0
and space_id != #{excludeId}
limit 1

select from data_trusted_space where space_name = #{spaceName} and is_del = 0
and space_id != #{excludeId}
limit 1

select count(*) from data_resource
where is_del = 0
and (trusted_space = #{spaceId}

    or trusted_space is null

)
